import React, { useState, useRef } from 'react';
import axios from 'axios';
import { API_URL } from '../utils/api';

const VideoProcessor = ({ colorblindType, mode }) => {
  const [selectedFile, setSelectedFile] = useState(null);
  const [processing, setProcessing] = useState(false);
  const [error, setError] = useState(null);
  const [success, setSuccess] = useState(null);
  const fileInputRef = useRef(null);

  const handleFileSelect = (e) => {
    const file = e.target.files[0];
    if (file) {
      setSelectedFile(file);
      setError(null);
      setSuccess(null);
    }
  };

  const handleDrop = (e) => {
    e.preventDefault();
    const file = e.dataTransfer.files[0];
    if (file && file.type.startsWith('video/')) {
      setSelectedFile(file);
      setError(null);
      setSuccess(null);
    }
  };

  const handleDragOver = (e) => {
    e.preventDefault();
    e.currentTarget.classList.add('dragover');
  };

  const handleDragLeave = (e) => {
    e.preventDefault();
    e.currentTarget.classList.remove('dragover');
  };

  const processVideo = async () => {
    if (!selectedFile) {
      setError('Please select a video file first');
      return;
    }

    // Check file size (warn if too large)
    const maxSize = 100 * 1024 * 1024; // 100MB
    if (selectedFile.size > maxSize) {
      setError(`Video file is too large (${(selectedFile.size / 1024 / 1024).toFixed(2)} MB). Maximum size is 100 MB.`);
      return;
    }

    setProcessing(true);
    setError(null);
    setSuccess(null);

    try {
      const formData = new FormData();
      formData.append('video', selectedFile);
      formData.append('colorblind_type', colorblindType);
      formData.append('mode', mode);

      const result = await axios.post(`${API_URL}/process-video`, formData, {
        headers: {
          'Content-Type': 'multipart/form-data',
        },
        timeout: 300000, // 5 minutes timeout for large videos
      });

      if (result.data.success) {
        const message = result.data.message || 
          `Video processed successfully! Output file: ${result.data.output_file}`;
        setSuccess(message);
      } else {
        setError(result.data.error || 'Failed to process video');
      }
    } catch (err) {
      console.error('Video processing error:', err);
      let errorMessage = 'Error processing video';
      
      if (err.response?.data?.error) {
        errorMessage = err.response.data.error;
      } else if (err.code === 'ECONNABORTED' || err.message.includes('timeout')) {
        errorMessage = 'Video processing timed out. The video may be too large or the server is busy.';
      } else if (err.code === 'ECONNREFUSED') {
        errorMessage = 'Cannot connect to backend server. Please ensure the Flask server is running.';
      } else if (err.message) {
        errorMessage = err.message;
      }
      
      setError(errorMessage);
    } finally {
      setProcessing(false);
    }
  };

  const downloadVideo = async () => {
    if (!selectedFile) return;
    
    try {
      const response = await axios.get(`${API_URL}/download/processed_${selectedFile.name}`, {
        responseType: 'blob',
      });
      
      const url = window.URL.createObjectURL(new Blob([response.data]));
      const link = document.createElement('a');
      link.href = url;
      link.setAttribute('download', `processed_${selectedFile.name}`);
      document.body.appendChild(link);
      link.click();
      link.remove();
    } catch (err) {
      setError('Failed to download video');
    }
  };

  return (
    <div className="component-container">
      <h2>Video Processor</h2>
      
      <div
        className="upload-area"
        onDrop={handleDrop}
        onDragOver={handleDragOver}
        onDragLeave={handleDragLeave}
        onClick={() => fileInputRef.current?.click()}
      >
        <input
          ref={fileInputRef}
          type="file"
          accept="video/*"
          onChange={handleFileSelect}
        />
        <p>Click or drag and drop a video here</p>
        <p style={{ fontSize: '14px', color: '#666', marginTop: '10px' }}>
          Supported formats: MP4, AVI, MOV
        </p>
      </div>

      {selectedFile && (
        <div style={{ margin: '20px 0', padding: '15px', background: '#f8f9ff', borderRadius: '8px' }}>
          <p><strong>Selected file:</strong> {selectedFile.name}</p>
          <p><strong>Size:</strong> {(selectedFile.size / 1024 / 1024).toFixed(2)} MB</p>
        </div>
      )}

      {error && <div className="error">{error}</div>}
      {success && <div className="success">{success}</div>}

      <div style={{ textAlign: 'center', marginTop: '20px', display: 'flex', gap: '10px', justifyContent: 'center' }}>
        <button
          className="button"
          onClick={processVideo}
          disabled={!selectedFile || processing}
        >
          {processing ? 'Processing...' : 'Process Video'}
        </button>
        {success && (
          <button
            className="button"
            onClick={downloadVideo}
          >
            Download Processed Video
          </button>
        )}
      </div>
    </div>
  );
};

export default VideoProcessor;
